/* Minimal drop-in replacement for webcam.js (Webcam.set / attach / snap / upload).
   Uses the browser camera API. Works on http://127.0.0.1 and http://localhost. */
(function (global) {
    var cfg = { width: 320, height: 240, dest_width: 320, dest_height: 240,
                image_type: 'jpeg', image_quality: 90, fps: 30 };
    var video = null;

    var Webcam = {
        set: function (o) { for (var k in o) { cfg[k] = o[k]; } },

        attach: function (selector) {
            var box = document.querySelector(selector);
            video = document.createElement('video');
            video.autoplay = true;
            video.playsInline = true;
            video.muted = true;
            video.style.width = cfg.width + 'px';
            video.style.height = cfg.height + 'px';
            video.style.background = '#000';
            video.style.objectFit = 'cover';
            box.innerHTML = '';
            box.appendChild(video);
            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                box.innerHTML = '<p style="color:red">Camera not supported in this browser.</p>';
                return;
            }
            navigator.mediaDevices.getUserMedia({
                video: { width: cfg.dest_width, height: cfg.dest_height, frameRate: cfg.fps }
            }).then(function (stream) { video.srcObject = stream; })
              .catch(function (e) {
                box.innerHTML = '<p style="color:red">Cannot access camera: ' + e.message + '</p>';
              });
        },

        snap: function (callback) {
            if (!video || !video.videoWidth) { alert('Camera is not ready yet.'); return; }
            var c = document.createElement('canvas');
            c.width = cfg.dest_width;
            c.height = cfg.dest_height;
            c.getContext('2d').drawImage(video, 0, 0, c.width, c.height);
            callback(c.toDataURL('image/' + cfg.image_type, cfg.image_quality / 100));
        },

        // Sends the picture as a file field named "webcam" (what Flask reads with request.files)
        upload: function (data_uri, url, callback) {
            var parts = data_uri.split(',');
            var mime = parts[0].match(/:(.*?);/)[1];
            var bin = atob(parts[1]);
            var arr = new Uint8Array(bin.length);
            for (var i = 0; i < bin.length; i++) { arr[i] = bin.charCodeAt(i); }
            var form = new FormData();
            form.append('webcam', new Blob([arr], { type: mime }), 'webcam.jpg');
            fetch(url, { method: 'POST', body: form })
                .then(function (r) { return r.text().then(function (t) { callback(r.status, t); }); })
                .catch(function (e) { callback(0, 'Network error: ' + e.message); });
        }
    };
    global.Webcam = Webcam;
})(window);
